class Solution:
    def longestBeautifulSubstring(self, word: str) -> int:
        best = 0
        length = 1
        kinds = 1
        for i in range(1, len(word)):
            if word[i] < word[i - 1]:
                length = 1
                kinds = 1
            else:
                length += 1
                if word[i] != word[i - 1]:
                    kinds += 1
            if kinds == 5:
                best = max(best, length)
        return best

code.Java:
import java.io.*;
import java.util.*;

class Solution {
    public int longestBeautifulSubstring(String word) {
        int best = 0, length = 1, kinds = 1;
        for (int i = 1; i < word.length(); i++) {
            if (word.charAt(i) < word.charAt(i - 1)) {
                length = 1;
                kinds = 1;
            } else {
                length++;
                if (word.charAt(i) != word.charAt(i - 1)) kinds++;
            }
            if (kinds == 5) best = Math.max(best, length);
        }
        return best;
    }
}

